          clamp(
            resize.startHeight + dy,
            resize.minHeight,
            maxHeight
          );


        win.style.setProperty(
          'width',
          `${Math.round(width)}px`,
          'important'
        );

        win.style.setProperty(
          'height',
          `${Math.round(height)}px`,
          'important'
        );


