const stickerPackLabels = Object.create(null);
window.__CLQ_ASSET_MANIFEST = __CLQ_INLINE_ASSET_MANIFEST;

async function loadAssetManifest() {
  let manifest = window.__CLQ_ASSET_MANIFEST;

  // Always use the embedded manifest in the browser.
  // This makes the app safe to open directly from file://.
  // On GitHub Pages, the build workflow regenerates this embedded manifest
  // whenever assets are added, so no runtime fetch is required.

  if (!manifest || !Array.isArray(manifest.frames) || !Array.isArray(manifest.stickerPacks)) {
    console.error('CL★Q asset manifest is missing or invalid.');
    return false;
  }

  // Frames are filesystem-driven.
  FRAMES = manifest.frames.map((item, index) => ({
    id: item.id || `frame-${index + 1}`,
    label: item.label || item.id || `frame ${index + 1}`,
    src: resolveAssetSrc(item.src || `assets/frames/${item.file || ''}`)
  }));

  // Rebuild sticker packs from filesystem folders.
  Object.keys(packs).forEach(id => delete packs[id]);
  Object.keys(stickerPackLabels).forEach(id => delete stickerPackLabels[id]);

  Object.entries(EMOJI_PACKS).forEach(([id, pack]) => {
    packs[id] = pack.items.map((emoji, index) => ({
      src: emojiSVG(emoji),
      emoji,
      label: `${pack.label} ${index + 1}`
    }));
    stickerPackLabels[id] = pack.label;
  });

  manifest.stickerPacks.forEach(pack => {
    const files = Array.isArray(pack.files) ? pack.files : [];
    const directory = pack.directory || `assets/stickers/${pack.id}`;
    packs[pack.id] = files.map((file, index) => ({
      src: resolveAssetSrc(`${directory}/${file}`),
      label: `${pack.label} ${index + 1}`
    }));
    stickerPackLabels[pack.id] = pack.label;
  });

  // A guaranteed first-view pack: real PNG stickers + emoji stickers together.
  // This prevents the drawer from ever opening on a sparse/blank category.
  const firstPhysicalPack = manifest.stickerPacks.find(p => Array.isArray(p.files) && p.files.length);
  const physicalFeatured = firstPhysicalPack ? firstPhysicalPack.files.slice(0, 10).map((file, i) => ({
    src: resolveAssetSrc(`${firstPhysicalPack.directory || `assets/stickers/${firstPhysicalPack.id}`}/${file}`),
    label: `featured sticker ${i + 1}`
  })) : [];
  const featuredEmoji = Object.values(EMOJI_PACKS).flatMap(pack => pack.items.slice(0, 2).map((emoji, i) => ({
    src: emojiSVG(emoji), emoji, label: `${pack.label} ${i + 1}`
  })));
  packs.featured = [...physicalFeatured, ...featuredEmoji.slice(0, 8)];
  stickerPackLabels.featured = 'FEATURED ✦';
  state.pack = 'featured';
  renderFrames();
  const landingFrame = $('#landingFrame1');
  if (landingFrame && FRAMES[0]) {
    landingFrame.src = FRAMES[0].src;
    landingFrame.alt = FRAMES[0].label;
  }
  renderFolderTabs();
  return true;
}

function renderFolderTabs() {
  const tabs = $('#stickerTabs');
  if (!tabs) return;
  tabs.innerHTML = '';
  tabs.classList.add('sticker-tab-strip');
  Object.keys(packs).forEach(id => {
    const button = document.createElement('button');
    button.className = `tab${state.pack === id ? ' active' : ''}`;
    button.textContent = stickerPackLabels[id] || id.replace(/(^|-)/g, match => match === '-' ? ' ' : '').toUpperCase();
    button.onclick = () => {
      state.pack = id;
      $$('#stickerTabs .tab').forEach(tab => tab.classList.remove('active'));
      button.classList.add('active');
      renderStickers();
    };
    tabs.appendChild(button);
  });
  renderStickers();
}

const notificationItems = [];
let lastNotificationSoundAt = 0;
function addNotification(message, icon = '✦') {
  notificationItems.unshift({ message, icon, time: new Date() });
  const now = performance.now();
  if (now - lastNotificationSoundAt > 1000) { lastNotificationSoundAt = now; playAssetSound('notifAudio'); }
  const list = $('#notificationList');
  if (list) {
    list.innerHTML = notificationItems.slice(0, 8).map(item => `<div class="notification-item">${item.icon} ${item.message}<time>${item.time.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</time></div>`).join('');
  }
  const count = $('#notificationCount');
  if (count) count.textContent = String(Math.min(notificationItems.length, 9));
}

const soundLastPlayed = new Map();

function playAssetSound(id) {
  const audio = $('#' + id);
  if (!audio) return;

  const now = performance.now();
  const minGap =
    id === 'notifAudio' ? 1000 :
      id === 'shutterAudio' ? 80 :
        120;

  const last = soundLastPlayed.get(id) || -Infinity;
  if (now - last < minGap) return;

  soundLastPlayed.set(id, now);
  try {
    audio.pause();
    audio.currentTime = 0;
    const p = audio.play();
    if (p?.catch) p.catch(() => { });
  } catch (_) { }
}

/* Mouse click sounds use cloned audio nodes so clicks can overlap. */
function playOverlappingAssetSound(id, volume = 0.52) {
  const source = $('#' + id);
  if (!source) return;
  try {
    const copy = source.cloneNode(true);
    copy.volume = volume;
    copy.currentTime = 0;
    copy.style.display = 'none';
    document.body.appendChild(copy);
    const cleanup = () => { try { copy.remove(); } catch (_) { } };
    copy.addEventListener('ended', cleanup, { once: true });
    const p = copy.play();
    if (p?.catch) p.catch(cleanup);
  } catch (_) { }
}

let clickAudioCtx = null;
function playClickSound(kind = 'click') {
  if (kind === 'click') {
    playOverlappingAssetSound('clickEndAudio', 0.52);
    return;
  }
  try {
    clickAudioCtx ||= new (window.AudioContext || window.webkitAudioContext)();
    if (clickAudioCtx.state === 'suspended') clickAudioCtx.resume();
    const now = clickAudioCtx.currentTime;
    const o = clickAudioCtx.createOscillator();
    const g = clickAudioCtx.createGain();
    const f =
      kind === 'close' ? 180 :
        kind === 'min' ? 420 :
          kind === 'grab' ? 760 :
            kind === 'resize' ? 520 :
              kind === 'count' ? 560 :
                kind === 'go' ? 880 : 720;
    o.type = 'square';
    o.frequency.setValueAtTime(f, now);
    o.frequency.exponentialRampToValueAtTime(f * .62, now + .035);
    g.gain.setValueAtTime(.0001, now);
    g.gain.exponentialRampToValueAtTime(kind === 'grab' ? .025 : .055, now + .002);
    g.gain.exponentialRampToValueAtTime(.0001, now + .035);
    o.connect(g).connect(clickAudioCtx.destination);
    o.start(now);
    o.stop(now + .04);
  } catch (_) { }
}
function bindBackgroundMusic() {
  const audio = $('#backgroundMusic');
  const panel = $('#volumePanel');
  const task = $('#volumeTask');
  const toggle = $('#musicToggle');
  const slider = $('#musicVolume');
  const output = $('#musicVolumeValue');
  if (!audio || !panel || !task || !toggle || !slider || !output) return;
  audio.volume = Number(slider.value) / 100;
  task.onclick = () => { panel.hidden = !panel.hidden; };
  toggle.onclick = async () => {
    if (audio.paused) {
      await audio.play();
      toggle.textContent = '❚❚ music on';
      task.textContent = '🔊 music on';
    } else {
      audio.pause();
      toggle.textContent = '▶ music off';
      task.textContent = '🔇 music off';
    }
  };
  slider.oninput = () => {
    audio.volume = Number(slider.value) / 100;
    output.value = `${slider.value}%`;
    output.textContent = `${slider.value}%`;
  };
}
function installCutePointer() {
  if (window.__clqCutePointerInstalled) return;
  window.__clqCutePointerInstalled = true;

  /*
   * The cute pointer is purely decorative.
   * NEVER hide the native browser cursor. This keeps the app usable
   * even when the image is unavailable or a browser blocks local assets.
   */
  const layer = document.createElement('div');
  layer.className = 'clq-pointer-layer';
  document.body.appendChild(layer);

  const pointer = document.createElement('img');
  pointer.className = 'clq-cursor-image';
  pointer.alt = '';
  pointer.draggable = false;
  pointer.decoding = 'async';
  pointer.style.display = 'none';
  layer.appendChild(pointer);

  let customReady = false;
  let imageReady = false;

  const disableCustomPointer = () => {
    customReady = false;
    imageReady = false;
    pointer.style.display = 'none';
    /* Ensure any stale class from an older build cannot hide the cursor. */
    document.documentElement.classList.remove('clq-custom-cursor-ready');
    document.body.classList.remove('clq-custom-cursor-ready');
  };

  pointer.onload = () => {
    imageReady = true;
    customReady = true;
    pointer.style.display = 'block';
    document.documentElement.classList.add('clq-custom-cursor-ready');
  };

  pointer.onerror = disableCustomPointer;

  /* Direct relative asset URL: works from file:// and normal HTTP(S). */
  pointer.src = 'assets/y2k-cursor.png';

  window.addEventListener('pointermove', e => {
    if (customReady && imageReady) {
      pointer.style.left = `${e.clientX - 18}px`;
      pointer.style.top = `${e.clientY - 18}px`;

      const movingWindow = document.querySelector('.window.is-dragging');
      if (movingWindow) {
        const dx = e.movementX || 0;
        const dy = e.movementY || 0;
        const angle = Math.max(-12, Math.min(12,
          Math.atan2(dy, dx || 1) * 180 / Math.PI
        ));
        pointer.style.setProperty('--cursor-drag-rotate', `${angle}deg`);
      } else {
        pointer.style.setProperty('--cursor-drag-rotate', '0deg');
      }
    }

    if (!customReady || !imageReady) return;

    const now = performance.now();
    if (!window.__clqCursorLastSpark) window.__clqCursorLastSpark = 0;
    if (now - window.__clqCursorLastSpark < 55) return;
    window.__clqCursorLastSpark = now;

    const dot = document.createElement('span');
    dot.className = 'cursor-spark';
    dot.textContent = ['✦', '♡', '⋆', '·'][Math.floor(Math.random() * 4)];
    dot.style.left = `${e.clientX}px`;
    dot.style.top = `${e.clientY}px`;
    layer.appendChild(dot);
    setTimeout(() => dot.remove(), 650);
  }, { passive: true });

  let pointerDownX = 0, pointerDownY = 0, pointerDragged = false;
  window.addEventListener('pointerdown', e => {
    pointerDownX = e.clientX; pointerDownY = e.clientY; pointerDragged = false;
    if (!customReady || !imageReady) return;
    const burst = document.createElement('span');
    burst.className = 'cursor-burst';
    burst.textContent = '✦';
    burst.style.left = `${e.clientX}px`;
    burst.style.top = `${e.clientY}px`;
    layer.appendChild(burst);
    setTimeout(() => burst.remove(), 500);
  }, { passive: true });
  window.addEventListener('pointermove', e => {
    if (Math.hypot(e.clientX - pointerDownX, e.clientY - pointerDownY) > 5) pointerDragged = true;
  }, { passive: true });
  window.addEventListener('pointerup', () => {
    if (customReady && imageReady) pointer.style.setProperty('--cursor-drag-rotate', '0deg');
  }, { passive: true });
  if (!document.body.dataset.clqClickSoundBound) {
    document.body.dataset.clqClickSoundBound = '1';

    let downTarget = null;
    let downPointer = null;
    let moved = false;

    document.addEventListener('pointerdown', e => {
      const target = e.target?.closest?.('button,a,input,select,textarea,.titlebar');
      if (!target || e.button !== 0) return;
      if (target.matches('input[type="range"]')) return;
      downTarget = target;
      downPointer = e.pointerId;
      moved = false;
      playOverlappingAssetSound('clickStartAudio', 0.52);
    }, true);

    document.addEventListener('pointermove', e => {
      if (downPointer !== e.pointerId) return;
      if (Math.hypot(e.movementX || 0, e.movementY || 0) > 6) moved = true;
    }, { capture: true, passive: true });

    document.addEventListener('pointerup', e => {
      if (!downTarget || downPointer !== e.pointerId) return;
      const target = e.target?.closest?.('button,a,input,select,textarea,.titlebar');
      if (!moved && target && !document.body.classList.contains('dragging-window')) {
        playOverlappingAssetSound('clickEndAudio', 0.52);
      }
      downTarget = null;
      downPointer = null;
      moved = false;
    }, true);

    document.addEventListener('pointercancel', () => {
      downTarget = null;
      downPointer = null;
      moved = false;
    }, true);
  }
}

function bindNotifications() {
  const task = $('#notificationTask');
  const panel = $('#notificationPanel');
  const clear = $('#clearNotifications');
  if (!task || !panel || !clear) return;
  task.onclick = () => { panel.hidden = !panel.hidden; };
  clear.onclick = () => {
    notificationItems.length = 0;
    $('#notificationList').innerHTML = '';
    $('#notificationCount').textContent = '0';
  };
  addNotification('welcome to the CL★Q! beta ✦ become a beta tester!', '💌');
  window.setTimeout(() => addNotification('new sparkle spotted on the desktop', '🫧'), 9000);
}
function toggleDockPet() {
  const pet = $('#dockPet');
  const toggle = $('#dockPetToggle');
  if (!pet) return;
  pet.classList.toggle('hidden');
  if (toggle) toggle.classList.toggle('visible', pet.classList.contains('hidden'));
  if (!pet.classList.contains('hidden')) animateDockPet();
}
function animateDockPet() {
  const pet = $('#dockPet');
  const dock = document.querySelector('.dock-right');
  if (!pet || !dock || pet.classList.contains('hidden')) return;
  const travel = Math.max(0, dock.clientWidth - 220);
  pet.style.left = `${12 + Math.random() * travel}px`;
  window.setTimeout(animateDockPet, 12000 + Math.random() * 6000);
}


function photoIndexFromPoint(canvas, e) {
  if (!canvas) return -1;
  const l = layout();
  if (!state.shots || !state.shots.some(Boolean)) return -1;
  const r = canvas.getBoundingClientRect();
  if (!r.width || !r.height) return -1;
  const x = (e.clientX - r.left) / r.width * canvas.width;
  const y = (e.clientY - r.top) / r.height * canvas.height;
  const outer = 18, topPad = 18, bottomPad = Math.min(state.bottomPad, Math.max(0, canvas.height - outer - 40)), gap = 10, cols = l.kind === 'grid' ? l.cols : 1, rows = Math.ceil(l.shots / cols);
  const availH = Math.max(40, canvas.height - topPad - bottomPad - gap * (rows - 1));
  const baseCellH = availH / rows;
  const baseCellW = (canvas.width - outer * 2 - gap * (cols - 1)) / cols;
  for (let i = 0; i < l.shots; i++) {
    const col = i % cols, row = Math.floor(i / cols), boxW = baseCellW, boxH = baseCellH, cellW = boxW * state.photoScale, cellH = boxH * state.photoScale, px = outer + col * (boxW + gap) + (boxW - cellW) / 2, py = topPad + row * (boxH + gap) + (boxH - cellH) / 2;
    if (x >= px && x <= px + cellW && y >= py && y <= py + cellH && state.shots[i]) return i;
  }
  return -1;
}
function bindPreviewPhotoClicks() {
  ['setupCanvas', 'stripCanvas', 'finalCanvas'].forEach(id => {
    const c = $('#' + id);
    if (!c || c.dataset.photoClickBound === '1') return;
    c.dataset.photoClickBound = '1';
    c.addEventListener('pointerdown', e => {
      const idx = photoIndexFromPoint(c, e);
      if (idx < 0) return;
      state.selectedPhotoIndex = idx;
      const sel = $('#capturePreviewWindow .selection-readout');
      if (sel) sel.textContent = `selected photo ${idx + 1} · updating preview…`;
      refreshFlowPreviews();
    });
  });
}
function bindHomePaint() {
  const canvas = $('#homePaintCanvas');
  if (!canvas || canvas.dataset.bound === '1') return;
  canvas.dataset.bound = '1';

  const pad = canvas.parentElement;
  const ctx = canvas.getContext('2d');
  let drawing = false;

  const resize = () => {
    const r = pad.getBoundingClientRect();
    const dpr = Math.min(2, window.devicePixelRatio || 1);
    canvas.width = Math.max(1, Math.round(r.width * dpr));
    canvas.height = Math.max(1, Math.round(r.height * dpr));
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.strokeStyle = '#ff4fa3';
    ctx.lineWidth = 3;
  };

  const pos = e => {
    const r = canvas.getBoundingClientRect();
    return { x: e.clientX - r.left, y: e.clientY - r.top };
  };

  let penCtx = null, penOsc = null, penGain = null;

  const startPenSound = () => {
    if (penOsc) return;
    try {
      penCtx ||= new (window.AudioContext || window.webkitAudioContext)();
      if (penCtx.state === 'suspended') penCtx.resume();
      penOsc = penCtx.createOscillator();
      penGain = penCtx.createGain();
      penOsc.type = 'triangle';
      penOsc.frequency.value = 165;
      penGain.gain.value = 0.018;
      penOsc.connect(penGain).connect(penCtx.destination);
      penOsc.start();
    } catch (_) { }
  };

  const stopPenSound = () => {
    if (!penOsc) return;
    try { penOsc.stop(); } catch (_) { }
    try { penOsc.disconnect(); } catch (_) { }
    try { penGain?.disconnect(); } catch (_) { }
    penOsc = null;
    penGain = null;
  };

  canvas.addEventListener('pointerdown', e => {
    drawing = true;
    try { canvas.setPointerCapture(e.pointerId); } catch (_) { }
    const p = pos(e);
    ctx.beginPath();
    ctx.moveTo(p.x, p.y);
    startPenSound();
    e.stopPropagation();
  });

  canvas.addEventListener('pointermove', e => {
    if (!drawing) return;
    const p = pos(e);
    ctx.lineTo(p.x, p.y);
    ctx.stroke();
    e.stopPropagation();
  });

  const stop = e => {
    if (!drawing) return;
    drawing = false;
    stopPenSound();
    if (e?.pointerId != null) {
      try { canvas.releasePointerCapture(e.pointerId); } catch (_) { }
    }
  };

  canvas.addEventListener('pointerup', stop);
  canvas.addEventListener('pointercancel', stop);
  canvas.addEventListener('lostpointercapture', stop);
  window.addEventListener('resize', resize);
  resize();
}
function bindHomeStickers() {
  const playground = $('#homeStickerPlayground');
  if (!playground || playground.dataset.bound) return;
  playground.dataset.bound = '1';
  $$('.home-sticker', playground).forEach(sticker => {
    let drag = null;
    sticker.addEventListener('pointerdown', event => {
      const r = playground.getBoundingClientRect();
      const s = sticker.getBoundingClientRect();
      drag = { pointerId: event.pointerId, ox: event.clientX - s.left, oy: event.clientY - s.top };
      sticker.classList.add('dragging');
      sticker.setPointerCapture(event.pointerId);
      event.preventDefault();
    });
    sticker.addEventListener('pointermove', event => {
      if (!drag || event.pointerId !== drag.pointerId) return;
      const r = playground.getBoundingClientRect();
      const landing = $('#landing').getBoundingClientRect();
      const minX = landing.left - r.left;
      const maxX = landing.right - r.left - sticker.offsetWidth;
      const minY = landing.top - r.top;
      const maxY = landing.bottom - r.top - sticker.offsetHeight;
      const x = Math.max(minX, Math.min(maxX, event.clientX - r.left - drag.ox));
      const y = Math.max(minY, Math.min(maxY, event.clientY - r.top - drag.oy));
      sticker.style.left = `${x}px`;
      sticker.style.top = `${y}px`;
    });
    const stop = event => {
      if (!drag || (event.pointerId !== undefined && event.pointerId !== drag.pointerId)) return;
      drag = null;
      sticker.classList.remove('dragging');
    };
    sticker.addEventListener('pointerup', stop);
    sticker.addEventListener('pointercancel', stop);
  });
}

