function renderStickers() {
  const g = $('#stickerGrid'); if (!g) return;
  g.innerHTML = '';
  const list = packs[state.pack] || [];
  if (!list.length) { g.innerHTML = '<div class="sticker-empty">no stickers in this pack yet ✦</div>'; return; }
  list.forEach(s => {
    const b = document.createElement('button'); b.type = 'button'; b.className = 'sticker'; b.title = s.label;
    const isEmoji = String(s.src).startsWith('data:image/svg+xml');
    if (isEmoji) { const span = document.createElement('span'); span.className = 'sticker-emoji'; span.textContent = s.emoji || '✦'; b.appendChild(span); }
    else {
      const im = document.createElement('img');
      im.decoding = 'async';
      im.loading = 'eager';
      im.alt = s.label;
      im.src = resolveAssetSrc(s.src);
      im.onload = () => b.classList.add('asset-ready');
      im.onerror = () => { b.classList.add('asset-missing'); b.innerHTML = '<span class="sticker-fallback">✦</span>'; };
      b.appendChild(im);
    }
    b.onclick = () => addSticker(resolveAssetSrc(s.src));
    g.appendChild(b);
  });
}
function initTabs() { renderFolderTabs(); }
function addSticker(src) {
  const safeSrc = resolveAssetSrc(src);
  const st = { src: safeSrc, x: .5 + (Math.random() - .5) * .24, y: .5 + (Math.random() - .5) * .18, size: .10 + Math.random() * .055, r: (Math.random() - .5) * .25 };
  state.stickers.push(st); selectedSticker = state.stickers.length - 1; refreshFlowPreviews();
}
function stickerHit(px, py, w, h) { for (let i = state.stickers.length - 1; i >= 0; i--) { const st = state.stickers[i], sx = st.x * w, sy = st.y * h, sw = st.size * w; if (Math.hypot(px - sx, py - sy) < sw * .7) return i } return -1 }
