  canvas.addEventListener('pointerdown', e => { if (!drawState.enabled) return; const hit = stickerHit((e.clientX - canvas.getBoundingClientRect().left) / canvas.getBoundingClientRect().width * canvas.width, (e.clientY - canvas.getBoundingClientRect().top) / canvas.getBoundingClientRect().height * canvas.height, canvas.width, canvas.height); if (hit >= 0) return; const p = pos(e); active = { pen: drawState.pen, color: drawState.color, points: [p] }; drawState.strokes.push(active); canvas.setPointerCapture(e.pointerId); refresh(); e.stopPropagation() });
