  canvas.addEventListener('pointerup', end); canvas.addEventListener('pointercancel', end); canvas.addEventListener('lostpointercapture', end);
  $$('#drawToolRow .draw-tool').forEach(b => b.onclick = () => { drawState.pen = b.dataset.pen; $$('#drawToolRow .draw-tool').forEach(x => x.classList.toggle('active', x === b)); updateDrawStatus() });
  const color = $('#drawColor'); if (color) color.oninput = () => { drawState.color = color.value; updateDrawStatus() };
  const toggle = $('#drawToggle'); if (toggle) toggle.onclick = () => { drawState.enabled = !drawState.enabled; toggle.textContent = drawState.enabled ? '✎ DRAWING: ON' : '✎ DRAWING: OFF'; canvas.classList.toggle('drawing-disabled', !drawState.enabled); updateDrawStatus() };
