  const pos = e => { const r = c.getBoundingClientRect(); return { x: (e.clientX - r.left) / r.width * c.width, y: (e.clientY - r.top) / r.height * c.height } };
  c.addEventListener('pointerdown', e => { const p = pos(e), i = stickerHit(p.x, p.y, c.width, c.height); if (i < 0) return; selectedSticker = i; dragSticker = { i, ox: p.x / c.width - state.stickers[i].x, oy: p.y / c.height - state.stickers[i].y }; c.setPointerCapture(e.pointerId); refreshFlowPreviews() });
