async function canvasToBlobSafe(canvas, type = 'image/png', quality = .98) {
  if (!canvas) throw new Error('missing canvas');
  try {
    const blob = await new Promise((resolve, reject) => canvas.toBlob(b => b ? resolve(b) : reject(new Error('canvas blob unavailable')), type, quality));
    if (blob && blob.size) return blob;
  } catch (e) { console.warn('canvas.toBlob failed', e); }
  const dataUrl = canvas.toDataURL(type, quality);
  const res = await fetch(dataUrl);
  const blob = await res.blob();
  if (!blob.size) throw new Error('empty image blob');
  return blob;
}
async function downloadBlob(blob, name) {
  if (!blob || !blob.size) throw new Error('empty download');
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a'); a.href = url; a.download = name; a.rel = 'noopener';
  a.style.position = 'fixed'; a.style.left = '-9999px'; document.body.appendChild(a);
  try { a.click(); } finally { a.remove(); setTimeout(() => URL.revokeObjectURL(url), 15000); }
  return true;
}
async function downloadCanvas(canvas, name) {
  const blob = await canvasToBlobSafe(canvas, 'image/png', .98);
  return downloadBlob(blob, name);
}
