async function getFaceDetector() {
  if (faceDetectionState.detectorPromise) return faceDetectionState.detectorPromise;
  faceDetectionState.detectorPromise = (async () => {
    try { if (window.FaceDetector) return { type: 'native', detector: new window.FaceDetector({ fastMode: true, maxDetectedFaces: 5 }) }; } catch (_) { }
    try {
      const vision = await import('https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.35/+esm');
      const fs = await vision.FilesetResolver.forVisionTasks('https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.35/wasm');
      const detector = await vision.FaceDetector.createFromOptions(fs, { baseOptions: { modelAssetPath: 'https://storage.googleapis.com/mediapipe-models/face_detector/blaze_face_short_range/float16/1/blaze_face_short_range.tflite' }, runningMode: 'IMAGE', minDetectionConfidence: .45, minSuppressionThreshold: .3 });
      return { type: 'mediapipe', detector };
    } catch (e) { console.warn('CL★Q face tracker unavailable; using safe fallback positioning.', e); return null; }
  })();
  return faceDetectionState.detectorPromise;
}

