  tintEl.style.background = overlay ? overlay[0] : 'transparent';
  tintEl.style.mixBlendMode = overlay ? overlay[1] : 'normal';
  if (v === 'lightleak') { tintEl.style.background = 'linear-gradient(135deg,rgba(255,130,70,.30),rgba(255,90,150,.16) 18%,rgba(255,255,255,0) 48%,rgba(255,210,100,.06))'; tintEl.style.mixBlendMode = 'screen'; }
