function renderFilterCards() { const g = $('#filterGrid'); if (!g) return; g.innerHTML = ''; FILTER_META.forEach(([id, label, cls]) => { const b = document.createElement('button'); b.className = 'filter-card' + (state.filter === id ? ' active' : ''); b.dataset.filter = id; const pv = document.createElement('div'); pv.className = 'filter-preview ' + cls; const nm = document.createElement('div'); nm.className = 'filter-name'; nm.textContent = label; b.append(pv, nm); b.onclick = () => setFilter(id); g.appendChild(b); }); }
