function renderFaceFilterCards() { const g = $('#faceFilterGrid'); if (!g) return; g.innerHTML = ''; FACE_FILTER_META.forEach(([id, label, cls]) => { const b = document.createElement('button'); b.className = 'filter-card face-filter-card' + (state.faceFilter === id ? ' active' : ''); b.dataset.faceFilter = id; const pv = document.createElement('div'); pv.className = 'filter-preview ' + cls + ' emoji-face-preview'; pv.textContent = id === 'dog' ? '🐶' : id === 'hearts' ? '❤️' : '✦'; const nm = document.createElement('div'); nm.className = 'filter-name'; nm.textContent = id === 'dog' ? 'dog tracker' : id === 'hearts' ? 'floating hearts' : 'none'; b.append(pv, nm); b.onclick = () => setFaceFilter(id); g.appendChild(b); }); }
