(function () {
  const q = s => document.querySelector(s);
  window.primeStepWindows = function (step) {
    const parents = {
      2: q('#captureDesktop'),
      3: document.querySelector('.custom-layout'),
      4: document.querySelector('.download-layout')
    };
    const parent = parents[step];
    if (!parent) return;
    parent.classList.remove('clq-step2-frozen');
    parent.style.removeProperty('width');
    parent.style.removeProperty('height');
    parent.style.removeProperty('position');
    parent.style.removeProperty('overflow');
    [
      '#capturePreviewWindow', '#setupPreview', '#mainWindow', '#controlWindow',
      '.customize-preview', '#stickerWindow', '#styleWindow', '#frameWindow', '#drawWindow',
      '#downloadWindow'
    ].forEach(sel => {
      const el = q(sel);
      if (!el || !parent.contains(el)) return;
      el.classList.remove('drag-free'); delete el.dataset.clqFree;
      ['position', 'left', 'top', 'right', 'bottom', 'width', 'height', 'min-width', 'max-width', 'overflow', 'margin', 'grid-area', 'transform'].forEach(prop => el.style.removeProperty(prop));
    });
  };
})();

// Boot the app after the DOM/assets are ready.
function initEnvironmentNotice() {
  document.documentElement.dataset.clqProtocol = location.protocol;
  if (location.protocol !== 'file:') return;
  const old = document.getElementById('status');
  if (old && !document.getElementById('fileProtocolHint')) {
    const hint = document.createElement('div');
    hint.id = 'fileProtocolHint';
    hint.className = 'file-protocol-hint';
    hint.innerHTML = '♡ local file mode · photos, stickers & decoration are offline-safe · camera/video capture works best from <b>localhost or HTTPS</b>';
    old.parentElement?.appendChild(hint);
  }
}
function initMicroInteractions() {
  document.addEventListener('pointerdown', e => {
    if (!(e.target instanceof Element)) return;

    const el = e.target.closest(
      'button,.aero-btn,.tiny-btn,.filter-card,.sticker,.quick-sticker,.creative-action,.tab'
    );

    if (!el) return;

    el.classList.remove('micro-pop');
    void el.offsetWidth;
    el.classList.add('micro-pop');
  });

  document.addEventListener('pointerenter', e => {
    if (!(e.target instanceof Element)) return;

    const el = e.target.closest(
      '.sticker,.quick-sticker,.filter-card,.home-photo,.hero-mini-chip,.creative-pill'
    );

    if (el) {
      el.classList.add('micro-hover');
    }
  }, true);

  document.addEventListener('pointerleave', e => {
    if (!(e.target instanceof Element)) return;

    const el = e.target.closest(
      '.sticker,.quick-sticker,.filter-card,.home-photo,.hero-mini-chip,.creative-pill'
    );

    if (el) {
      el.classList.remove('micro-hover');
    }
  }, true);

  const homeShuffle = $('#homeShuffle');

  if (homeShuffle) {
    homeShuffle.onclick = () => {
      const picks = [
        'dreamy cloud day ☁️',
        'bubblegum pixels 🩷',
        'sparkle overload ✦',
        'kawaii radio 📻',
        'aqua arcade 🫧',
        'internet cafe angel 💿'
      ];

      const text = picks[Math.floor(Math.random() * picks.length)];

      const spans = homeShuffle.querySelectorAll('span');
      const p = spans[2];

      if (p) {
        p.textContent = text;
      }

      document.body.classList.remove('home-shimmer-burst');
      void document.body.offsetWidth;
      document.body.classList.add('home-shimmer-burst');
    };
  }
}
window.addEventListener('load', () => { initMicroInteractions(); initEnvironmentNotice(); });
window.addEventListener('load', init);

window.__CLQ_VERSION = 'v4-debug-polish';
